// Pozn.: klient se jmenuje "sb", ne "supabase" – knihovna z CDN už definuje globální proměnnou "supabase"
// (kdyby ji kód znovu deklaroval, prohlížeč by hlásil "Identifier 'supabase' has already been declared").
// Úložiště přihlášení: „Zůstat přihlášený“ → trvale (localStorage), jinak jen do zavření karty (sessionStorage)
const KEEP_KEY = 'tj-keep';
const authStorage = {
  keep() { try { return localStorage.getItem(KEEP_KEY) !== '0'; } catch (e) { return true; } },
  getItem(k) { try { return sessionStorage.getItem(k) ?? localStorage.getItem(k); } catch (e) { return null; } },
  setItem(k, v) { try { if (authStorage.keep()) { localStorage.setItem(k, v); sessionStorage.removeItem(k); } else { sessionStorage.setItem(k, v); localStorage.removeItem(k); } } catch (e) {} },
  removeItem(k) { try { localStorage.removeItem(k); sessionStorage.removeItem(k); } catch (e) {} }
};
const sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY, {auth: {storage: authStorage}});


