/* =====================================================================
   4. Util – pomocné funkce bez vazby na data
   ===================================================================== */
class Util {
  /** Ochrana proti vložení HTML (vždy použít u textů zadaných uživatelem). */
  /** Příjmení = poslední slovo jména ("Dominik Kondaš" → "Kondaš"). */
  static surname(n) { const w = String(n || '').trim().split(/\s+/); return w[w.length - 1] || ''; }
  static esc(s) { return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
  /** Řetězec bezpečný do onclick='...' (apostrofy, uvozovky). */
  static q(s) { return Util.esc(String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")); }
  /** Text bez diakritiky a malými písmeny – pro hledání. */
  static norm(s) { return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim(); }
  /** Pondělí zobrazovaného týdne (od pátku do neděle se ukazuje už příští týden). */
  static weekStart() {
    const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() + 2);
    d.setDate(d.getDate() - (d.getDay() + 6) % 7);
    return d;
  }
  /** Datum dne v zobrazovaném týdnu: 0 → objekt Date pro pondělí. */
  static dayDate(d) { const x = Util.weekStart(); x.setDate(x.getDate() + d); return x; }
  /** Datum jako "2026-10-19" (pro databázi, v místním čase). */
  static iso(x) { return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; }
  /** Den v týdnu (0 = Po) z "2026-10-19". */
  static dayIndex(iso) { const [y, m, d] = iso.split('-').map(Number); return Math.round((new Date(y, m - 1, d) - Util.weekStart()) / 864e5); }
  /** Barva docházky: 70–100 % zelená, 40–69 % žlutá, 0–39 % červená. */
  static attLvl(p) { return p >= CONFIG.attGood ? 'g' : p >= CONFIG.attMid ? 'y' : 'r'; }
  static attCls(p) { return {g: 'cg', y: 'cw', r: 'cr'}[Util.attLvl(p)]; }
  static attBg(p)  { return 'var(--' + Util.attLvl(p) + ')'; }
  static attPill(p) { return {g: 'ok', y: 'wa', r: 'no'}[Util.attLvl(p)]; }
  /** "2026-10-12" → "Po 12.10." */
  static isoShort(iso) { const [y, m, d] = String(iso).split('-').map(Number); if (!y) return '—'; return `${CONFIG.days[(new Date(y, m - 1, d).getDay() + 6) % 7]} ${d}.${m}.`; }
  /** Popisek dne: 0 → "Po 19.10." */
  static date(d) { const x = Util.dayDate(d); return `${CONFIG.days[d]} ${x.getDate()}.${x.getMonth() + 1}.`; }
  /** Časová značka zprávy z databáze: "čt 15.10. 18:02". */
  static stamp(ts) {
    const d = new Date(ts); if (isNaN(d)) return '';
    return `${CONFIG.days[(d.getDay() + 6) % 7].toLowerCase()} ${d.getDate()}.${d.getMonth() + 1}. ${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`;
  }
  /** Dnešní datum pro trenérský deník: "16.10.". */
  static today() { const d = new Date(); return `${d.getDate()}.${d.getMonth() + 1}.`; }
  /** Datum z databáze "2026-10-11" → "11.10.". */
  static short(iso) { const [, m, d] = iso.split('-').map(Number); return `${d}.${m}.`; }
  /** Telefon bez mezer (pro odkaz tel:). */
  static phone(x) { return String(x).replace(/[^\d+]/g, ''); }
  /** "16:30" → 990 minut. */
  static toMin(x) { const [a, b] = x.split(':'); return +a * 60 + +b; }
  /** 990 → "16:30". */
  static toTime(m) { return Math.floor(m / 60) + ':' + String(m % 60).padStart(2, '0'); }
  /** Červený odznak s počtem (nebo nic, když je 0). */
  static badge(n) { return n ? `<i class="bd">${n}</i>` : ''; }
  /** Název hřiště: 'A' → "Hřiště A", 'Hala' → "Hala". */
  static venue(f) { return f == 'Hala' ? 'Hala' : f == 'C' ? 'Hřiště C – Loučka' : f == 'B' ? 'Hřiště B – Umělka' : 'Hřiště ' + f; }
  /** Stabilní odstín barvy podle textu (pro avatary). */
  static hue(s) { return [...s].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 360, 7); }
  /** Věk a ročník hráče: "9 let (ročník 2017)". */
  static age(m) { return m.by ? `${new Date().getFullYear() - m.by} let (ročník ${m.by})` : 'ročník neuvedený'; }
  /** Iniciály hráče z celého jména. */
  static initials(m) { return (m.full || m.n).split(/\s+/).map(w => w[0]).slice(0, 2).join('').toUpperCase(); }
  /** Avatar uživatele (trenér, vedení): fotka, nebo barevné iniciály z jména. */
  static userAvatar(u, size) {
    const name = u.name || u.email || '?', src = Photos.src(u.ph);
    if (src) return `<img class="av" style="width:${size}px;height:${size}px;margin:0" src="${src}" alt="Fotka">`;
    const h = Util.hue(name);
    return `<div class="av" ${Photos.isPath(u.ph) ? `data-ph="${u.ph}"` : ''} style="width:${size}px;height:${size}px;margin:0;font-size:${Math.round(size*.38)}px;background:linear-gradient(135deg,hsl(${h},65%,45%),hsl(${(h+50)%360},65%,32%))">${Util.esc(name.split(/\s+/).map(w => w[0]).slice(0, 2).join('').toUpperCase())}</div>`;
  }
  /** Kulatý avatar hráče: fotka, nebo barevné iniciály. */
  static avatar(m, size) {
    const src = Photos.src(m.ph);
    if (src) return `<img class="av" style="width:${size}px;height:${size}px" src="${src}" alt="Fotka hráče" decoding="async">`;
    const h = Util.hue(m.n);
    return `<div class="av" ${Photos.isPath(m.ph) ? `data-ph="${m.ph}"` : ''} style="width:${size}px;height:${size}px;font-size:${Math.round(size*.38)}px;background:linear-gradient(135deg,hsl(${h},65%,45%),hsl(${(h+50)%360},65%,32%))">${Util.esc(Util.initials(m))}</div>`;
  }
}
const $ = sel => document.querySelector(sel);   // zkratky používané v celém kódu
const esc = Util.esc;
